import { createHash } from "crypto";

export interface FileChangeEvent {
  eventId: string;
  workspaceId: string;
  fileId: string;
  version: number;
  contentHash: string;
  deviceId: string;
  kind: "upsert" | "delete";
}

interface Entry {
  expiresAt: number;
}

export class ChangeDeduplicator {
  private readonly seen = new Map<string, Entry>();

  constructor(
    private readonly windowMs: number,
    private readonly maxEntries: number,
    private readonly now: () => number = Date.now
  ) {}

  private key(e: FileChangeEvent): string {
    return createHash("sha1")
      .update(`${e.workspaceId}|${e.fileId}|${e.kind}|${e.contentHash}`)
      .digest("hex");
  }

  isDuplicate(e: FileChangeEvent): boolean {
    this.evictExpired();
    const k = this.key(e);
    const entry = this.seen.get(k);
    return entry !== undefined && entry.expiresAt > this.now();
  }

  remember(e: FileChangeEvent): void {
    const k = this.key(e);
    this.seen.delete(k);
    this.seen.set(k, { expiresAt: this.now() + this.windowMs });
    while (this.seen.size > this.maxEntries) {
      const oldest = this.seen.keys().next().value as string;
      this.seen.delete(oldest);
    }
  }

  private evictExpired(): void {
    const t = this.now();
    for (const [k, v] of this.seen) {
      if (v.expiresAt > t) break;
      this.seen.delete(k);
    }
  }
}

import { ChangeDeduplicator, FileChangeEvent } from "./dedup";
import { SyncIndex } from "./syncIndex";
import { DeviceNotifier } from "./notifier";
import { Logger } from "./logger";

export class SyncEventProcessor {
  private readonly dedup = new ChangeDeduplicator(10 * 60 * 1000, 200_000);

  constructor(
    private readonly index: SyncIndex,
    private readonly notifier: DeviceNotifier,
    private readonly log: Logger
  ) {}

  async process(event: FileChangeEvent): Promise<void> {
    if (this.dedup.isDuplicate(event)) {
      this.log.debug({ eventId: event.eventId, fileId: event.fileId }, "dropping duplicate change");
      return;
    }

    const applied = await this.index.applyIfNewer(event);
    if (!applied) {
      this.log.info(
        { fileId: event.fileId, version: event.version },
        "stale change ignored"
      );
      this.dedup.remember(event);
      return;
    }

    await this.notifier.fanOut(event.workspaceId, {
      fileId: event.fileId,
      version: event.version,
      kind: event.kind,
      originDevice: event.deviceId,
    });
    this.dedup.remember(event);
  }
}

import type { Pool } from "pg";
import type { FileChangeEvent } from "./dedup";

export class SyncIndex {
  constructor(private readonly pool: Pool) {}

  async applyIfNewer(e: FileChangeEvent): Promise<boolean> {
    const { rowCount } = await this.pool.query(
      `INSERT INTO file_index (workspace_id, file_id, version, content_hash, deleted)
       VALUES ($1, $2, $3, $4, $5)
       ON CONFLICT (workspace_id, file_id) DO UPDATE
         SET version = EXCLUDED.version,
             content_hash = EXCLUDED.content_hash,
             deleted = EXCLUDED.deleted
       WHERE file_index.version < EXCLUDED.version`,
      [e.workspaceId, e.fileId, e.version, e.contentHash, e.kind === "delete"]
    );
    return (rowCount ?? 0) > 0;
  }
}
